 '('	error ')' { $$ = gen_noop(); } |
 '[' error ']' { $$ = gen_noop(); } |
-Term '[' error ']' { $$ = $1; } |
+IndexPrefix error ']' { $$ = $1; } |
 '{' error '}' { $$ = gen_noop(); }
PATCH

