git apply --recount <<'PATCH'
--- a/docs/content/manual/manual.yml
+++ b/docs/content/manual/manual.yml
@@ -408,6 +408,15 @@
           `. ["foo"]` (`.foo` above is a shorthand version of this, but
           only for identifier-like strings).

+          Bracket indexes can be chained with or without a dot:
+          `. ["foo"].["bar"]` and `. ["foo"]["bar"]` are equivalent.
+          The same applies to iteration and slices, such as `.foo.[]`
+          and `.foo.[1:3]`.
+
+        examples:
+          - program: '.["foo"].["bar"]'
+            input: '{"foo": {"bar": 42}}'
+            output: [42]
+
       - title: "Array Index: `.[<number>]`"
         body: |
PATCH
make -j4 > /tmp/jq-chain-build.log 2>&1 && ./jq -L tests/modules --run-tests tests/jq.test > /tmp/jq-chain-after.log 2>&1; result=$?; tail -12 /tmp/jq-chain-build.log; test ! -f /tmp/jq-chain-after.log || tail -5 /tmp/jq-chain-after.log; exit "$result"

